$ErrorActionPreference = "Stop"

$root = (Get-Location).Path
$ws = Join-Path $root "runtime\workspaces\ahos-autopilot"
$pkg = Join-Path $ws "ahos_core"
$python = Join-Path $root ".venv\Scripts\python.exe"

$skillsRoot = Join-Path $ws ".agents\skills"
$privateRoot = Join-Path $root "runtime\private\animation-studio\audio"
$privateRadar = Join-Path $privateRoot "technology-radar.local.json"
$audioDb = Join-Path $privateRoot "audio-manifest.db"

$patcher = Join-Path $env:TEMP "studio006_backlog.py"

Write-Host "=== STUDIO-006 AUDIO + SKILLS + TECHNOLOGY RADAR FOUNDATION ==="
Write-Host "Live TTS calls: 0"
Write-Host "Paid provider calls: 0"
Write-Host "API spend: USD 0"
Write-Host ""

if (-not (Test-Path $python)) { throw "AHOS Python venv not found." }
if (-not (Test-Path $pkg)) { throw "AHOS package not found." }

New-Item -ItemType Directory -Force -Path $skillsRoot | Out-Null
New-Item -ItemType Directory -Force -Path $privateRoot | Out-Null

[IO.File]::WriteAllBytes((Join-Path $pkg "ahos\skill_registry.py"), [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes((Join-Path $pkg "ahos\technology_radar.py"), [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes((Join-Path $pkg "ahos\audio_pipeline.py"), [Convert]::FromBase64String(""))

[IO.File]::WriteAllBytes((Join-Path $pkg "tests\test_skill_registry.py"), [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes((Join-Path $pkg "tests\test_technology_radar.py"), [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes((Join-Path $pkg "tests\test_audio_pipeline.py"), [Convert]::FromBase64String(""))


$dir = Join-Path $skillsRoot "character-voice-continuity"
New-Item -ItemType Directory -Force -Path $dir | Out-Null
[IO.File]::WriteAllBytes((Join-Path $dir "SKILL.md"), [Convert]::FromBase64String(""))


$dir = Join-Path $skillsRoot "multilingual-dubbing"
New-Item -ItemType Directory -Force -Path $dir | Out-Null
[IO.File]::WriteAllBytes((Join-Path $dir "SKILL.md"), [Convert]::FromBase64String(""))


$dir = Join-Path $skillsRoot "tts-provider-selection"
New-Item -ItemType Directory -Force -Path $dir | Out-Null
[IO.File]::WriteAllBytes((Join-Path $dir "SKILL.md"), [Convert]::FromBase64String(""))


$dir = Join-Path $skillsRoot "audio-qa"
New-Item -ItemType Directory -Force -Path $dir | Out-Null
[IO.File]::WriteAllBytes((Join-Path $dir "SKILL.md"), [Convert]::FromBase64String(""))


[IO.File]::WriteAllBytes($privateRadar, [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($patcher, [Convert]::FromBase64String(""))

$old = $env:PYTHONPATH
Push-Location $pkg
try {
    $env:PYTHONPATH = $pkg

    Write-Host "Running STUDIO-006 focused tests..."
    & $python -m pytest `
        tests\test_skill_registry.py `
        tests\test_technology_radar.py `
        tests\test_audio_pipeline.py -q
    if ($LASTEXITCODE -ne 0) { throw "STUDIO-006 focused tests failed." }

    Write-Host "Running full AHOS + Studio regression suite..."
    & $python -m pytest -q
    if ($LASTEXITCODE -ne 0) { throw "Full regression suite failed." }

    & $python $patcher $backlogPath
    if ($LASTEXITCODE -ne 0) { throw "STUDIO-006 backlog update failed." }

    Write-Host "Validating Agent Skills discovery..."
    & $python -c "from ahos.skill_registry import SkillRegistry; r=SkillRegistry(r'$skillsRoot'); s=r.discover_all(); print('SKILLS DISCOVERED:', len(s)); [print(' -', x.name) for x in s]"
    if ($LASTEXITCODE -ne 0) { throw "Skill registry validation failed." }

    Write-Host "Initializing persistent private audio manifest..."
    & $python -c "from ahos.audio_pipeline import AudioManifestStore; AudioManifestStore(r'$audioDb'); print('AUDIO MANIFEST DB: READY')"
    if ($LASTEXITCODE -ne 0) { throw "Audio manifest initialization failed." }
}
finally {
    Pop-Location
    $env:PYTHONPATH = $old
    Remove-Item $patcher -Force -ErrorAction SilentlyContinue
}

git -C $ws add `
    ahos_core/ahos/skill_registry.py `
    ahos_core/ahos/technology_radar.py `
    ahos_core/ahos/audio_pipeline.py `
    ahos_core/tests/test_skill_registry.py `
    ahos_core/tests/test_technology_radar.py `
    ahos_core/tests/test_audio_pipeline.py `
    ahos_core/STUDIO_BACKLOG.json `
    .agents/skills

$staged = git -C $ws diff --cached --name-only
if ($staged -match "technology-radar\.local|audio-manifest\.db") {
    throw "Privacy guard failed: private audio/radar data was staged."
}

if ($staged) {
    git -C $ws -c user.name="Miniverse Autopilot" -c user.email="miniverse@local.invalid" `
        commit -m "feat(studio): add skill-native multilingual audio foundation"
    if ($LASTEXITCODE -ne 0) { throw "git commit failed." }
    git -C $ws push origin HEAD
    if ($LASTEXITCODE -ne 0) { throw "git push failed." }
}

Write-Host ""
Write-Host "=== STUDIO-006 FOUNDATION COMPLETE ==="
Write-Host "Agent Skills-compatible registry: PASS"
Write-Host "Progressive skill discovery/loading: PASS"
Write-Host "Technology Radar: PASS"
Write-Host "Provider-agnostic audio registry: PASS"
Write-Host "Commercial-license gating: PASS"
Write-Host "Multilingual localization planning: PASS"
Write-Host "Voice continuity skill: PASS"
Write-Host "Dubbing skill: PASS"
Write-Host "Audio QA skill: PASS"
Write-Host "Persistent private audio manifest: PASS"
Write-Host "Live TTS calls: 0"
Write-Host "Paid provider calls: 0"
Write-Host "API spend: USD 0"
Write-Host ""
Write-Host "STUDIO-006 STATUS: IN PROGRESS"
Write-Host "NEXT: connect + live-verify existing miniverse-kokoro-tts-prod endpoint."
